or:#839189;margin-top:.15rem}.fields{display:grid;grid-template-columns:1fr 1fr;gap:.75rem;margin-top:.85rem}.fields label{display:grid;gap:.35rem}.fields .wide{grid-column:1/-1}.fields label>span{font-size:.72rem;font-weight:800}.fields label>small{font-size:.65rem;color:#b73838}.fields label>em{font-size:.62rem;color:#839189;font-style:normal}.security-note{margin-top:.75rem;padding:.65rem;border-radius:10px;background:#f4f8f5;color:#60746a;font-size:.69rem}.password-input{position:relative}.password-input button{position:absolute;inset-inline-end:5px;top:5px;width:34px;height:34px;border:0;background:#f1f5f3;border-radius:8px;color:#52685d}main>footer{display:flex;justify-content:flex-end;gap:.55rem}main>footer .btn{min-width:160px;min-height:46px;font-weight:800}@media(max-width:820px){.profile-layout{grid-template-columns:1fr}.profile-card{position:static}.profile-card dl{display:grid;grid-template-columns:1fr 1fr;gap:0 .75rem}.branches{text-align:center}}@media(max-width:560px){.fields,.profile-card dl{grid-template-columns:1fr}.fields .wide{grid-column:auto}.form-card,.profile-card{border-radius:13px}.profile-layout{gap:.65rem}main>footer{position:sticky;bottom:0;background:#f5f8f6;padding:.6rem;z-index:3}main>footer .btn{min-width:0;flex:1}}
</style>
